const crypto = require('crypto');
const SECRET_KEY = $env["SECRET_KEY"] || '73kZtS56JFkRuRpfuUj08cmOMtDzH8ZGMaKsfcZewQMqMvRIojf70toDGajiDJPm';
const { access_token } = $json;

function base64urlUnescape(str) {
  str += new Array(5 - str.length % 4).join('=');
  return str.replace(/\-/g, '+').replace(/_/g, '/');
}

function verifyJWT(access_token, secret) {
  try {
    const parts = access_token.split('.')

    if (parts.length !== 3) {
      return { isValid: false, error: 'Token malformado' };
    }

    const [encodedHeader, encodedPayload, signature] = parts;

    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(encodedHeader + '.' + encodedPayload)
      .digest('base64')
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=/g, '');

    if (signature !== expectedSignature) {
      return { isValid: false, error: 'Assinatura inválida' };
    }

    const payload = JSON.parse(
      Buffer.from(base64urlUnescape(encodedPayload), 'base64').toString()
    );

    const now = Math.floor(Date.now() / 1000);
    if (payload.exp && payload.exp < now) {
      return { isValid: false, error: 'Token expirado' };
    }

    return { isValid: true, payload };
  } catch (error) {
    return { isValid: false, error: 'Erro ao processar access_token' };
  }
}

try {
  return verifyJWT(access_token, SECRET_KEY);
} catch (error) {
  return {
    isValid: false,
    access_token,
    error
  }
}
